import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Kanban Work","description":"","frontmatter":{},"headers":[],"relativePath":"zh/demo/kanban.md","filePath":"zh/demo/kanban.md"}'),i={name:"zh/demo/kanban.md"};function n(s,a,d,l,h,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="kanban-work" tabindex="-1">Kanban Work <a class="header-anchor" href="#kanban-work" aria-label="Permalink to &quot;Kanban Work&quot;">​</a></h1><p>第一个演示是 Kanban 工作空间：看板应用、数据、应用 Service，以及帮助构建和操作看板的 Harness。它展示完整可运行的工作空间如何被分享和继续使用。</p><div class="info custom-block"><p class="custom-block-title">演示状态</p><p>目前还没有公开的 Kanban <code>.work</code> 归档、录屏或截图。本页说明演示结构，以及如何用当前产品构建或导入看板。预构建的演示包尚未发布。</p></div><h2 id="包含什么" tabindex="-1">包含什么？ <a class="header-anchor" href="#包含什么" aria-label="Permalink to &quot;包含什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>在演示中的作用</th></tr></thead><tbody><tr><td>工作空间</td><td>托管存储中的应用源码和看板数据。</td></tr><tr><td>Service</td><td>运行看板网页和 API 的容器。</td></tr><tr><td>Harness</td><td>构建和操作看板所需的模型、工具、指令和历史。</td></tr><tr><td>配置</td><td>镜像、命令、已声明的 HTTP 端口、工作空间挂载和就绪检查。</td></tr></tbody></table><p>一个应用 Service 就足以构建第一版看板。独立数据库 Service 可选；实际应用决定有哪些 Services。请检查 Service 列表，不要假设固定技术栈。</p><h2 id="在-piwork-中构建看板" tabindex="-1">在 Piwork 中构建看板 <a class="header-anchor" href="#在-piwork-中构建看板" aria-label="Permalink to &quot;在 Piwork 中构建看板&quot;">​</a></h2><p><a href="/piwork/zh/guide/installation.html">安装 Piwork</a>，打开 Desktop，创建并启动名为 <code>Kanban</code> 的 Work。在 Chat 中可以提出：</p><blockquote><p>在共享工作空间中构建一个简单 Kanban 看板，包含 Todo、Doing 和 Done 三列。将数据持久化到托管工作空间。使用可用的 Work Service 工具将应用声明为 Service，包含 HTTP 端口和就绪检查。检查运行中的 Service，并说明你验证了什么。</p></blockquote><p>这是一条给 Harness 的任务示例。结果取决于模型和环境；它不是安装命令，也不是经过验收的可下载演示。</p><p>在 Desktop 中打开 Service。添加卡片、移动卡片，然后重新加载应用，确认数据保留。通过 <strong>Files</strong> 检查应用文件。</p><h2 id="harness-做什么" tabindex="-1">Harness 做什么 <a class="header-anchor" href="#harness-做什么" aria-label="Permalink to &quot;Harness 做什么&quot;">​</a></h2><p>Harness 可以检查工作空间、编写应用、声明 Service、读取日志并验证运行状态。随后可以让它修改看板并检查结果。</p><p>如果看板实现了实验性 brain 的能力契约，还可以提供结构化查询和操作。这需要应用代码支持，普通 HTTP 访问不会自动提供这些能力。参见 <a href="/piwork/zh/spec/harness.html">Harness 规范</a>。</p><h2 id="验证可携带性" tabindex="-1">验证可携带性 <a class="header-anchor" href="#验证可携带性" aria-label="Permalink to &quot;验证可携带性&quot;">​</a></h2><ol><li>创建一个容易识别的卡片，并确认已经保存。</li><li>停止 Work，执行导出。</li><li>保存并检查 <code>.work</code> 文件。</li><li>导入到已配置自己模型的兼容第二个 Core。</li><li>启动导入的 Work，打开看板 Service。</li><li>确认卡片和文件存在，再继续修改看板。</li></ol><p>具体命令见<a href="/piwork/zh/guide/first-work.html">第一个 Work</a>。同样的流程也适用于可信演示发布者提供的归档。使用导入返回的新 ID，它代表一个新的 Work。</p><h2 id="演示材料" tabindex="-1">演示材料 <a class="header-anchor" href="#演示材料" aria-label="Permalink to &quot;演示材料&quot;">​</a></h2><p>录屏、截图和归档链接发布后会添加到这里。目前可以通过 <a href="https://github.com/pphboy/piwork/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>分享可复现的看板或报告问题。</p>',19)])])}const b=e(i,[["render",n]]);export{k as __pageData,b as default};
